export function DataTable<T extends { id: string }>({
  rows,
  columns,
  pageSize = 5,
  selected = [],
  onSelectionChange,
}: {
  rows: T[];
  columns: DataColumn<T>[];
  pageSize?: number;
  selected?: string[];
  onSelectionChange?: (ids: string[]) => void;
}) {
  const [page, setPage] = useState(0);
  const [sort, setSort] = useState<{
    key: keyof T & string;
    direction: 1 | -1;
  } | null>(null);
  const sorted = useMemo(
    () =>
      sort
        ? [...rows].sort(
            (a, b) =>
              (typeof a[sort.key] === "number" &&
              typeof b[sort.key] === "number"
                ? Number(a[sort.key]) - Number(b[sort.key])
                : String(a[sort.key]).localeCompare(String(b[sort.key]))) *
              sort.direction,
          )
        : rows,
    [rows, sort],
  );
  const size = Math.max(1, pageSize);
  const pages = Math.max(1, Math.ceil(rows.length / size));
  const current = Math.min(page, pages - 1);
  return (
    <div className="space-y-3">
      <div className="overflow-hidden rounded-lg border">
        <Table>
          <TableHeader>
            <TableRow>
              {onSelectionChange && (
                <TableHead className="w-10">
                  <span className="sr-only">Select row</span>
                </TableHead>
              )}
              {columns.map((column) => (
                <TableHead
                  key={column.key}
                  aria-sort={
                    sort?.key === column.key
                      ? sort.direction === 1
                        ? "ascending"
                        : "descending"
                      : "none"
                  }
                >
                  <button
                    type="button"
                    onClick={() => {
                      setSort({
                        key: column.key,
                        direction:
                          sort?.key === column.key && sort.direction === 1
                            ? -1
                            : 1,
                      });
                      setPage(0);
                    }}
                    className="flex items-center gap-2 py-3"
                  >
                    {column.label}
                    {sort?.key === column.key &&
                      (sort.direction === 1 ? (
                        <ArrowUp className="size-3" />
                      ) : (
                        <ArrowDown className="size-3" />
                      ))}
                  </button>
                </TableHead>
              ))}
            </TableRow>
          </TableHeader>
          <TableBody>
            {sorted.slice(current * size, (current + 1) * size).map((row) => (
              <TableRow
                key={row.id}
                data-state={selected.includes(row.id) ? "selected" : undefined}
              >
                {onSelectionChange && (
                  <TableCell>
                    <Checkbox
                      aria-label={`Select ${row.id}`}
                      checked={selected.includes(row.id)}
                      onCheckedChange={(checked) =>
                        onSelectionChange(
                          checked
                            ? [...selected, row.id]
                            : selected.filter((id) => id !== row.id),
                        )
                      }
                    />
                  </TableCell>
                )}
                {columns.map((column) => (
                  <TableCell key={column.key}>
                    {column.render?.(row) ?? String(row[column.key] ?? "")}
                  </TableCell>
                ))}
              </TableRow>
            ))}
            {!rows.length && (
              <TableRow>
                <TableCell
                  colSpan={columns.length + (onSelectionChange ? 1 : 0)}
                  className="h-24 text-center text-muted-foreground"
                >
                  No matching records.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>
      <div className="flex items-center justify-between text-xs text-muted-foreground">
        <span role="status">
          {rows.length === 0
            ? "0"
            : `${current * size + 1}–${Math.min((current + 1) * size, rows.length)}`}{" "}
          of {rows.length} records
          {selected.length > 0 ? ` · ${selected.length} selected` : ""}
        </span>
        <div className="flex items-center gap-3">
          <Button
            size="xs"
            variant="outline"
            disabled={current === 0}
            onClick={() => setPage(current - 1)}
          >
            Previous
          </Button>
          <span>
            {current + 1} / {pages}
          </span>
          <Button
            size="xs"
            variant="outline"
            disabled={current + 1 === pages}
            onClick={() => setPage(current + 1)}
          >
            Next
          </Button>
        </div>
      </div>
    </div>
  );
}

