export type JsonSchema =
  | boolean
  | {
      [key: string]: unknown;
      type?: string | string[];
      properties?: Record<string, JsonSchema>;
      required?: string[];
      enum?: unknown[];
      description?: string;
      title?: string;
      items?: JsonSchema;
    };
export interface ToolDefinition {
