import Ajv2020 from "ajv/dist/2020.js";
import addFormats from "ajv-formats";
import type { JsonSchema } from "@/lib/mcp/types";
const ajv = new Ajv2020({
  allErrors: true,
  strict: false,
  validateFormats: true,
  validateSchema: true,
});
addFormats(ajv);
export function validateArguments(
  schema: JsonSchema,
  value: unknown,
): string | null {
  try {
    const validate = ajv.compile(schema);
    if (validate(value)) return null;
    return (validate.errors ?? [])
      .map((e) => `${e.instancePath || "Input"} ${e.message}`)
      .join("; ");
  } catch {
    return "This schema cannot be validated locally. Provide a self-contained JSON Schema 2020-12 without external references.";
  }
}
export function simpleFields(
  schema: JsonSchema,
): schema is Exclude<JsonSchema, boolean> {
  if (
    !schema ||
    typeof schema !== "object" ||
    Array.isArray(schema) ||
    schema.type !== "object"
  )
    return false;
  if (
    schema.properties &&
    (typeof schema.properties !== "object" || Array.isArray(schema.properties))
  )
    return false;
  if (
    Object.keys(schema).some((k) =>
      [
        "$ref",
        "allOf",
        "anyOf",
        "oneOf",
        "if",
        "dependentSchemas",
        "patternProperties",
      ].includes(k),
    )
  )
    return false;
  return Object.values(schema.properties ?? {}).every(
    (p) =>
      p !== null &&
      typeof p === "object" &&
      !Array.isArray(p) &&
      ["string", "number", "integer", "boolean"].includes(String(p.type)) &&
      !p.$ref &&
      !p.anyOf &&
      !p.oneOf &&
      !p.allOf,
  );
}

"use client";
import { useId, useState } from "react";
import {
  Button,
  Input,
  Label,
  NativeCheckbox,
  NativeSelect,
  Textarea,
} from "@fabrials/ui";
import { simpleFields, validateArguments } from "@/lib/mcp/schema";
import { errorMessage, type JsonSchema } from "@/lib/mcp/types";
export function ArgumentsForm({
  schema,
  onSubmit,
  submitLabel = "Run tool",
  disabled = false,
  initialValues = {},
}: {
  schema: JsonSchema;
  onSubmit: (args: Record<string, unknown>) => unknown | Promise<unknown>;
  submitLabel?: string;
  disabled?: boolean;
  initialValues?: Record<string, unknown>;
}) {
  const id = useId();
  const [error, setError] = useState("");
  const [pending, setPending] = useState(false);
  const fields = simpleFields(schema) ? (schema.properties ?? {}) : null;
  const [json, setJson] = useState(JSON.stringify(initialValues, null, 2));
  return (
    <form
      className="space-y-4"
      onSubmit={async (event) => {
        event.preventDefault();
        if (pending || disabled) return;
        const data = new FormData(event.currentTarget);
        setError("");
        try {
          let args: Record<string, unknown>;
          if (!fields) args = JSON.parse(json);
          else {
            args = {};
            for (const [name, field] of Object.entries(fields)) {
              if (typeof field === "boolean") continue;
              const raw = data.get(name);
              const required =
                typeof schema !== "boolean" && schema.required?.includes(name);
              if (field.type === "boolean") {
                args[name] = field.enum ? raw === "true" : raw === "on";
                continue;
              }
              if (raw === "" && !required) continue;
              args[name] =
                field.type === "number" || field.type === "integer"
                  ? Number(raw)
                  : String(raw ?? "");
            }
          }
          if (!args || typeof args !== "object" || Array.isArray(args))
            throw new Error("Arguments must be a JSON object.");
          const invalid = validateArguments(schema, args);
          if (invalid) throw new Error(invalid);
          setPending(true);
          await onSubmit(args);
        } catch (e) {
          setError(errorMessage(e));
        } finally {
          setPending(false);
        }
      }}
    >
      {fields ? (
        Object.entries(fields).map(([name, field]) => {
          if (typeof field === "boolean") return null;
          const required =
            typeof schema !== "boolean" && schema.required?.includes(name);
          const fieldId = `${id}-${name}`;
          return (
            <div className="space-y-1.5" key={name}>
              <Label htmlFor={fieldId}>
                {field.title ?? name}
                {required && (
                  <span aria-label="required" className="text-muted-foreground">
                    *
                  </span>
                )}
              </Label>
              {field.enum ? (
                <NativeSelect
                  id={fieldId}
                  name={name}
                  required={required}
                  defaultValue={String(
                    initialValues[name] ?? field.default ?? "",
                  )}
                  disabled={pending || disabled}
                >
                  <option value="">Select…</option>
                  {field.enum.map((value, index) => (
                    <option key={index} value={String(value)}>
                      {String(value)}
                    </option>
                  ))}
                </NativeSelect>
              ) : field.type === "boolean" ? (
                <NativeCheckbox
                  id={fieldId}
                  name={name}
                  defaultChecked={Boolean(initialValues[name] ?? field.default)}
                  disabled={pending || disabled}
                />
              ) : (
                <Input
                  id={fieldId}
                  name={name}
                  type={
                    ["integer", "number"].includes(String(field.type))
                      ? "number"
                      : field.format === "date"
                        ? "date"
                        : field.format === "email"
                          ? "email"
                          : "text"
                  }
                  step={field.type === "integer" ? 1 : "any"}
                  min={
                    typeof field.minimum === "number"
                      ? field.minimum
                      : undefined
                  }
                  max={
                    typeof field.maximum === "number"
                      ? field.maximum
                      : undefined
                  }
                  required={required}
                  defaultValue={String(
                    initialValues[name] ?? field.default ?? "",
                  )}
                  disabled={pending || disabled}
                  aria-describedby={
                    field.description ? `${fieldId}-help` : undefined
                  }
                />
              )}
              {field.description && (
                <p
                  id={`${fieldId}-help`}
                  className="text-xs text-muted-foreground"
                >
                  {field.description}
                </p>
              )}
            </div>
          );
        })
      ) : (
        <div className="space-y-2">
          <Label htmlFor={id}>Arguments · JSON</Label>
          <Textarea
            id={id}
            value={json}
            onChange={(e) => setJson(e.target.value)}
            rows={8}
            spellCheck={false}
            className="font-mono text-xs"
            disabled={pending || disabled}
          />
          <p className="text-xs text-muted-foreground">
            This schema uses advanced JSON Schema features. Edit its arguments
            directly.
          </p>
        </div>
      )}
      {error && (
        <p role="alert" className="text-sm text-destructive">
          {error}
        </p>
      )}
      <Button type="submit" disabled={disabled || pending} aria-busy={pending}>
        {pending ? "Running…" : submitLabel}
      </Button>
    </form>
  );
}

"use client";
import { useState } from "react";
import { Button } from "@fabrials/ui";
import { cn } from "@/lib/utils";
export function safeUrl(value: unknown): string | undefined {
  if (typeof value !== "string") return;
  try {
    const url = new URL(value);
    return ["https:", "http:"].includes(url.protocol) ? url.href : undefined;
  } catch {
    return;
  }
}
function Json({ value }: { value: unknown }) {
  return (
    <pre className="max-h-96 overflow-auto whitespace-pre-wrap break-words rounded-lg bg-muted/70 p-4 font-mono text-xs leading-relaxed">
      {JSON.stringify(value, null, 2) ?? String(value)}
    </pre>
  );
}
function Content({ value }: { value: unknown }) {
  if (!value || typeof value !== "object") return <Json value={value} />;
  const block = value as Record<string, unknown>;
  if (block.type === "text" && typeof block.text === "string")
    return (
      <p className="whitespace-pre-wrap break-words text-sm leading-relaxed">
        {block.text}
      </p>
    );
  if (block.type === "resource_link" && safeUrl(block.uri))
    return (
      <a
        className="text-sm underline underline-offset-4"
        href={safeUrl(block.uri)}
        target="_blank"
        rel="noopener noreferrer"
      >
        {String(block.name ?? block.uri)}
      </a>
    );
  if (
    block.type === "resource" &&
    block.resource &&
    typeof block.resource === "object"
  ) {
    const resource = block.resource as Record<string, unknown>;
    return typeof resource.text === "string" ? (
      <pre className="max-h-80 overflow-auto whitespace-pre-wrap text-xs">
        {resource.text}
      </pre>
    ) : (
      <Json value={resource} />
    );
  }
  if (
    typeof block.data === "string" &&
    block.data.length <= 8_000_000 &&
    typeof block.mimeType === "string"
  ) {
    const src = `data:${block.mimeType};base64,${block.data}`;
    // Only inert raster formats are embedded; remote URLs and SVG are never executed.
    if (
      block.type === "image" &&
      /^image\/(png|jpeg|webp|gif)$/.test(block.mimeType)
    )
      return (
        <picture>
          <img
            src={src}
            alt="Tool result"
            className="max-h-80 max-w-full rounded-md object-contain"
          />
        </picture>
      );
    if (
      block.type === "audio" &&
      /^audio\/(mpeg|mp3|wav|ogg|webm)$/.test(block.mimeType)
    )
      return <audio controls src={src} aria-label="Tool audio result" />;
  }
  return <Json value={value} />;
}
export function ResultView({
  result,
  className,
}: {
  result: unknown;
  className?: string;
}) {
  const [raw, setRaw] = useState(false);
  const object =
    result && typeof result === "object"
      ? (result as Record<string, unknown>)
      : undefined;
  const content = Array.isArray(object?.content)
    ? object.content
    : Array.isArray(object?.contents)
      ? object.contents
      : null;
  return (
    <div className={cn("space-y-3", className)}>
      <div className="flex items-center justify-between">
        <span className="text-xs font-medium text-muted-foreground">
          Result
        </span>
        <Button
          variant="ghost"
